function looksBlocked(r: FetchResult): boolean {
  if (r.status === 0 || r.status === 401 || r.status === 403 || r.status === 429 || r.status >= 500) return true;
  return /cf-chl|challenge-platform|Just a moment\.\.\.|Attention Required|captcha/i.test(r.body.slice(0, 20000));   // Cloudflare-style challenge pages
}

async function rawView(ctx: BrowserContext, url: string, raw: FetchResult): Promise<PageView> {
  const page = await ctx.newPage();
  try {
    await page.route(u => u.href === url, route => route.fulfill({ status: raw.status || 200, contentType: raw.headers['content-type'] ?? 'text/html', body: raw.body }));   // serve the fetched bytes, do not refetch
    await page.goto(url, { waitUntil: 'domcontentloaded' });   // no scripts run: javaScriptEnabled is false on this context
    return await extract(page);
  } finally {
    await page.close();
  }
}

  // …

    // Do not wait for the load event: one slow image or tracker can hold it forever. Parse, then give
    // load and network idle a bounded chance so client-rendered content has time to appear.
    await page.goto(url, { waitUntil: 'domcontentloaded', timeout: timeoutMs });
    let loadTimedOut = false;
    await page.waitForLoadState('load', { timeout: Math.min(8000, timeoutMs) }).catch(() => { loadTimedOut = true; });   // bounded: 8 s, then carry on
    await page.waitForLoadState('networkidle', { timeout: Math.min(3000, timeoutMs) }).catch(() => undefined);   // give client rendering a moment
