export function findSecrets(text: string): SecretHit[] {
  const hits: SecretHit[] = [];
  const seen = new Set<string>();
  for (const p of SECRET_PATTERNS) {
    for (const m of text.matchAll(p.re)) {
      const v = m[0];
      if (seen.has(v)) continue;
      seen.add(v);
      hits.push({ kind: p.kind, severity: p.severity, preview: redact(v), note: p.note });   // never the value itself
    }
  }
  for (const m of text.matchAll(/\beyJ[A-Za-z0-9_-]{10,}\.eyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]{10,}/g)) {
    const v = m[0];
    if (seen.has(v)) continue;
    seen.add(v);
    const role = jwtPayload(v)?.role;
    if (role === 'service_role') hits.push({ kind: 'Supabase service_role key', severity: 'critical', preview: redact(v), note: 'Bypasses row-level security for the whole database. Rotate the JWT secret now.' });   // decode the JWT: role decides the severity
  }
  return hits;
}

export function isAllowed(robots: Robots, token: string, path: string): AccessDecision {
  const group = groupFor(robots, token);   // exact token group, else *, else none
  if (!group) return { allowed: true, matchedBy: 'none' };
  const matchedBy = group.agents[0] === '*' ? 'star' : 'exact';
  let best: RobotsRule | undefined;
  for (const r of group.rules) {
    if (!ruleRegex(r.path).test(path)) continue;
    if (!best || r.path.length > best.path.length || (r.path.length === best.path.length && r.allow && !best.allow)) best = r;   // longest rule wins
  }
  return { allowed: best ? best.allow : true, matchedBy, rule: best };
}

